/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `fn_CalculateTax`(
    p_Amount DECIMAL(10,2), 
    p_RegionID INT
) RETURNS decimal(10,2)
    DETERMINISTIC
BEGIN
    DECLARE v_Rate DECIMAL(5,2);
    DECLARE v_TaxAmount DECIMAL(10,2);

    -- Get the tax rate for the region (simplest logic)
    -- Assuming you have a default tax rule, e.g., RuleID = 1
    SELECT RatePercent INTO v_Rate
    FROM TaxRates 
    WHERE RegionID = p_RegionID 
    LIMIT 1;

    -- Handle case where no tax rate is found (Default to 0)
    IF v_Rate IS NULL THEN
        SET v_Rate = 0;
    END IF;

    SET v_TaxAmount = p_Amount * v_Rate;
    
    RETURN v_TaxAmount;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
