/*!50003 DROP PROCEDURE IF EXISTS `sp_ProcessSale` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ProcessSale`(
    IN p_StoreID INT,
    IN p_EmployeeID INT,
    IN p_CustomerID INT,  -- Can be NULL if guest
    IN p_PaymentMethodID INT,
    IN p_TotalAmount DECIMAL(10,2),
    OUT p_TransactionID INT -- Returns the new receipt ID to Java
)
BEGIN
    -- 1. Start a fail-safe transaction
    START TRANSACTION;

    -- 2. Create the Receipt Header
    INSERT INTO Transactions (StoreID, EmployeeID, CustomerID, Date, Total)
    VALUES (p_StoreID, p_EmployeeID, p_CustomerID, NOW(), p_TotalAmount);
    
    -- 3. Get the ID of the receipt we just made
    SET p_TransactionID = LAST_INSERT_ID();

    -- 4. Record the Payment
    INSERT INTO TransactionPayments (TransID, MethodID, Amount)
    VALUES (p_TransactionID, p_PaymentMethodID, p_TotalAmount);

    -- 5. Update Loyalty Points (If customer exists)
    IF p_CustomerID IS NOT NULL THEN
        UPDATE MajikkuRewards 
        SET CurrentPoints = CurrentPoints + (p_TotalAmount * 1) -- 1 point per dollar
        WHERE CustomerID = p_CustomerID;
    END IF;

    -- 6. Save everything permanently
    COMMIT;
END ;;
DELIMITER ;
